import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as d}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Kimi chat and Agent cheatsheet","description":"Look up only. Entries, slashes, and quotas are copied from official pages that opened. Two plan-name systems stay unmerged.","frontmatter":{"title":"Kimi chat and Agent cheatsheet","description":"Look up only. Entries, slashes, and quotas are copied from official pages that opened. Two plan-name systems stay unmerged.","domain":"product","tags":["chat"],"role":"cheatsheet"},"headers":[],"relativePath":"products/kimi/kimi-cheatsheet.md","filePath":"products/kimi/kimi-cheatsheet.md","lastUpdated":1787107158000}'),o={name:"products/kimi/kimi-cheatsheet.md"};function i(s,t,h,l,n,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="kimi-chat-and-agent-cheatsheet" tabindex="-1">Kimi chat and Agent cheatsheet <a class="header-anchor" href="#kimi-chat-and-agent-cheatsheet" aria-label="Permalink to &quot;Kimi chat and Agent cheatsheet&quot;">​</a></h1><p>Look up only. Numbers belong to the linked official page. Last verified: 2026-08-19.</p><p>This table has <strong>no</strong> Kimi Code CLI. Coding commands: <a href="/products/kimi-code/">Kimi Code</a>.</p><h2 id="official-entries" tabindex="-1">Official entries <a class="header-anchor" href="#official-entries" aria-label="Permalink to &quot;Official entries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Entry</th></tr></thead><tbody><tr><td>Workspace / chat</td><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td></tr><tr><td>Product family</td><td><a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">kimi.com/zh-cn/products</a></td></tr><tr><td>Agent</td><td><a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a></td></tr><tr><td>Agent Swarm</td><td><a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a></td></tr><tr><td>Kimi Claw</td><td><a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></td></tr><tr><td>Kimi Work (other product)</td><td><a href="https://www.kimi.com/products/kimi-work" target="_blank" rel="noreferrer">kimi.com/products/kimi-work</a></td></tr><tr><td>Kimi Code (other product)</td><td><a href="/products/kimi-code/">Kimi Code</a></td></tr><tr><td>API (other product)</td><td><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">platform.moonshot.cn</a></td></tr><tr><td>Help Center</td><td><a href="https://www.kimi.com/help" target="_blank" rel="noreferrer">help</a>, <a href="https://www.kimi.com/zh-hans/help" target="_blank" rel="noreferrer">zh-hans/help</a></td></tr><tr><td>Company / app</td><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td></tr></tbody></table><p>Home sidebar from <a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a>: Plugins, Scheduled Tasks, Slides, Swarm, Deep Research, Docs, Websites, Sheets, Design; Kimi Work, Kimi Code, Kimi Claw. New chat: <strong>⌘K</strong>.</p><p>App model switch (<a href="https://www.kimi.com/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent overview</a>): <strong>K3</strong> or <strong>K3 Swarm</strong>.</p><h2 id="commands-entries-that-appear-on-chat-help" tabindex="-1">Commands / entries that appear on chat help <a class="header-anchor" href="#commands-entries-that-appear-on-chat-help" aria-label="Permalink to &quot;Commands / entries that appear on chat help&quot;">​</a></h2><p>These are help-center strings, <strong>not</strong> the Kimi Code TUI.</p><table tabindex="0"><thead><tr><th>Input or control</th><th>What it does</th><th>Source</th></tr></thead><tbody><tr><td><code>/</code></td><td>Invoke Skills / plugins</td><td>Skills, Plugins, Scheduled Tasks</td></tr><tr><td><code>+</code></td><td>Plugins / upload / new project</td><td>Plugins, Projects</td></tr><tr><td><code>/skill-creator</code></td><td>Create a Skill in dialogue</td><td><a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">Skills</a></td></tr><tr><td><code>/stop</code></td><td>Force-stop a Claw in group chat</td><td><a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">group-chat</a></td></tr><tr><td>Create scheduled task</td><td>Sidebar scheduler</td><td><a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a></td></tr><tr><td>Create (Claw)</td><td>One-click cloud OpenClaw</td><td><a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a></td></tr><tr><td>Link existing OpenClaw</td><td>Attach a self-hosted instance</td><td>Same</td></tr><tr><td>Start Group Chat</td><td>Claw group</td><td>group-chat</td></tr><tr><td>Settings → Personalization → Memory Space</td><td>Memory UI</td><td><a href="https://www.kimi.com/help/features/memory-space" target="_blank" rel="noreferrer">Memory</a></td></tr><tr><td>Settings → Chat channels</td><td>Claw channels</td><td>Claw overview</td></tr></tbody></table><p>Official skill name examples: <code>docx</code>, <code>deep-research</code>, <code>sop-writer</code>, <code>event-etf-study</code>.</p><h2 id="membership-overview-music-names-usd" tabindex="-1">Membership overview (music names + USD) <a class="header-anchor" href="#membership-overview-music-names-usd" aria-label="Permalink to &quot;Membership overview (music names + USD)&quot;">​</a></h2><p>Source: <a href="https://www.kimi.com/help/membership/membership-overview" target="_blank" rel="noreferrer">membership-overview</a>. Chat <strong>K2.6 is free and does not consume credits</strong>. Membership features share one pool.</p><p>Table 1:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Moderato $19/mo</th><th>Allegretto $39/mo</th><th>Allegro $99/mo</th><th>Vivace $199/mo</th></tr></thead><tbody><tr><td>Agent credits*</td><td>60</td><td>150</td><td>360</td><td>720</td></tr><tr><td>Agent concurrent tasks</td><td>2</td><td>2</td><td>4</td><td>4</td></tr><tr><td>Agent speed priority</td><td>4×</td><td>4×</td><td>4×</td><td>4×</td></tr><tr><td>Professional database</td><td>2,000 calls</td><td>5,000</td><td>12,000</td><td>24,000</td></tr><tr><td>Kimi Code</td><td>Available</td><td>Available</td><td>Available</td><td>Available</td></tr></tbody></table><p>* Official footnote: approximate, typical-task token conversion, for reference only.</p><p>Table 2 (same page, chat/Agent rows):</p><table tabindex="0"><thead><tr><th>Feature</th><th>Moderato</th><th>Allegretto</th><th>Allegro</th><th>Vivace</th></tr></thead><tbody><tr><td>K3 extra-long chat (up to 1M tokens)</td><td>—</td><td>—</td><td>✅</td><td>✅</td></tr><tr><td>Scheduled tasks</td><td>10</td><td>15</td><td>20</td><td>25</td></tr><tr><td>Widget tasks</td><td>10</td><td>15</td><td>20</td><td>25</td></tr><tr><td>Projects</td><td>20</td><td>20</td><td>100</td><td>100</td></tr><tr><td>Project storage</td><td>20GB</td><td>20GB</td><td>50GB</td><td>50GB</td></tr><tr><td>Plugins</td><td>15+ types</td><td>15+</td><td>15+</td><td>15+</td></tr><tr><td>Agent Swarm</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Swarm concurrent subtasks</td><td>2</td><td>4</td><td>8</td><td>8</td></tr><tr><td>Goal Mode</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Kimi Claw (Web, Android, PC)</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Group chat with Claw</td><td>—</td><td>10</td><td>10</td><td>10</td></tr></tbody></table><p>Annual billing: official &quot;save up to <strong>$480/year</strong>&quot;. Kimi Code also has a <strong>5-hour / weekly</strong> rate limit.</p><h2 id="the-other-official-tier-names" tabindex="-1">The other official tier names <a class="header-anchor" href="#the-other-official-tier-names" aria-label="Permalink to &quot;The other official tier names&quot;">​</a></h2><p><a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a> and <a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a> use <strong>Free / Go / Pro / Max / Ultra</strong>. Official pages do <strong>not</strong> equate those rows to Moderato…. Do not invent a mapping.</p><p>Projects:</p><table tabindex="0"><thead><tr><th></th><th>Free</th><th>Go</th><th>Pro</th><th>Max</th><th>Ultra</th></tr></thead><tbody><tr><td>Projects</td><td>2</td><td>20</td><td>20</td><td>100</td><td>100</td></tr><tr><td>Project storage</td><td>500MB</td><td>20GB</td><td>20GB</td><td>50GB</td><td>50GB</td></tr></tbody></table><p>Scheduled Tasks (<strong>active at once</strong>; create count unlimited):</p><table tabindex="0"><thead><tr><th></th><th>Free</th><th>Go</th><th>Pro</th><th>Max</th><th>Ultra</th></tr></thead><tbody><tr><td>Scheduled tasks</td><td>2</td><td>6</td><td>15</td><td>20</td><td>25</td></tr></tbody></table><p>Project files: ≤ <strong>100 MB</strong> each, up to <strong>50</strong>.</p><p>Default schedule expiry: Daily +7 days; Weekly +1 month; Monthly +3 months.</p><h2 id="other-sourced-numbers" tabindex="-1">Other sourced numbers <a class="header-anchor" href="#other-sourced-numbers" aria-label="Permalink to &quot;Other sourced numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Number</th><th>Source</th></tr></thead><tbody><tr><td>Agent 20+ tools</td><td>Agent overview</td></tr><tr><td>Swarm ≤300 sub-agents, &gt;4000 tool calls, ~4.5×</td><td>Agent Swarm</td></tr><tr><td>Deep Research 10,000+ words</td><td>Agent overview</td></tr><tr><td>Sheets up to 1,000-row Excel</td><td>Agent overview</td></tr><tr><td>ClawHub 5,000+ skills</td><td>Agent overview / Claw intro</td></tr><tr><td>K3: 2.8T params, 1M tokens, native vision</td><td>Agent overview (2026-07-16)</td></tr><tr><td>One-click Claw: Allegretto+; default K2.6</td><td>Claw overview</td></tr><tr><td>Plugins: K3 / K3 Swarm / Deep Research / Websites / PPT; not Claw or Plus</td><td>Plugins</td></tr></tbody></table><h2 id="high-quality-sources" tabindex="-1">High-quality sources <a class="header-anchor" href="#high-quality-sources" aria-label="Permalink to &quot;High-quality sources&quot;">​</a></h2><p>Last verified: 2026-08-19. Official pages opened for this handbook only.</p><h3 id="first-party" tabindex="-1">First-party <a class="header-anchor" href="#first-party" aria-label="Permalink to &quot;First-party&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td><td>Workspace</td></tr><tr><td><a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">zh-cn/products</a></td><td>First-class products</td></tr><tr><td><a href="https://www.kimi.com/help" target="_blank" rel="noreferrer">help</a></td><td>EN help index</td></tr><tr><td><a href="https://www.kimi.com/zh-hans/help" target="_blank" rel="noreferrer">zh-hans/help</a></td><td>ZH help index</td></tr><tr><td><a href="https://www.kimi.com/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent overview</a></td><td>Agent steps</td></tr><tr><td><a href="https://www.kimi.com/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a></td><td>Swarm</td></tr><tr><td><a href="https://www.kimi.com/help/membership/membership-overview" target="_blank" rel="noreferrer">Membership overview</a></td><td>Plans and pool</td></tr><tr><td><a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a></td><td>Deploy</td></tr><tr><td><a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">Claw group chat</a></td><td>Conductor / <code>/stop</code></td></tr><tr><td><a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a></td><td>Projects</td></tr><tr><td><a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">Skills</a></td><td>Skills</td></tr><tr><td><a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a></td><td>Plugins</td></tr><tr><td><a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a></td><td>Scheduler</td></tr><tr><td><a href="https://www.kimi.com/help/features/memory-space" target="_blank" rel="noreferrer">Memory</a></td><td>Memory</td></tr><tr><td><a href="https://www.kimi.com/help/kimi-work/overview" target="_blank" rel="noreferrer">Kimi Work overview</a></td><td>Desktop (not expanded here)</td></tr><tr><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td><td>Company / app</td></tr><tr><td><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">platform.moonshot.cn</a></td><td>API</td></tr></tbody></table><h3 id="fetch-notes" tabindex="-1">Fetch notes <a class="header-anchor" href="#fetch-notes" aria-label="Permalink to &quot;Fetch notes&quot;">​</a></h3><p><code>www.kimi.com</code> sometimes resolves to 198.18.x for automated clients. Guessed help slugs land on an empty search page. Open the category page, then copy the slug.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./kimi.html">Tutorial</a></li><li><a href="./kimi-cookbook.html">Cookbook</a></li><li><a href="./kimi-glossary.html">Glossary</a></li></ul>',37)])])}const g=e(o,[["render",i]]);export{k as __pageData,g as default};
